from pydantic import BaseModel, field_validator, model_validator

class RefundDraft(BaseModel):
    customer_email: str
    order_id: str | None = None
    action: str
    refund_cents: int = 0
    needs_human_approval: bool = True

    @field_validator("customer_email")
    @classmethod
    def normalize_email(cls, v: str) -> str:
        cleaned = v.strip().lower()
        if "@" not in cleaned:
            raise ValueError("Invalid email format")
        return cleaned

    @model_validator(mode="after")
    def verify_refund_safety(self) -> "RefundDraft":
        if self.action == "issue_refund":
            if not self.order_id:
                raise ValueError("order_id is required when action is issue_refund")
            if not self.needs_human_approval:
                raise ValueError("refunds must always require human approval")
        return self

