from pydantic import BaseModel, ValidationError

def strip_json_fence(raw: str) -> str:
    text = raw.strip()
    if text.startswith("```"):
        lines = text.splitlines()
        if lines and lines[0].startswith("```"):
            lines = lines[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        text = "\n".join(lines).strip()
    return text

def validate_llm_output[T: BaseModel](raw_text: str, schema: type[T]) -> T:
    cleaned = strip_json_fence(raw_text)
    return schema.model_validate_json(cleaned)

from pydantic import BaseModel, ValidationError

class SafeTriageResult(BaseModel):
    category: str
    needs_human_approval: bool
    status: str
    draft_reply: str | None = None

def safe_triage(raw_llm_json: str) -> SafeTriageResult:
    try:
        # Attempt strict Pydantic validation
        decision = TriageDecision.model_validate_json(raw_llm_json)
        return SafeTriageResult(
            category=decision.category,
            needs_human_approval=decision.needs_human_approval,
            status="validated",
            draft_reply=decision.summary,
        )
    except ValidationError:
        # Log safe metric + structured diagnostic here, then route safely to human queue!
        return SafeTriageResult(
            category="other",
            needs_human_approval=True,
            status="fallback_manual_review",
            draft_reply=None,
        )

