import json
from langchain_core.tools import tool
from pydantic import BaseModel, ConfigDict, Field

class OrderLookupArgs(BaseModel):
    model_config = ConfigDict(extra="forbid")
    order_id: str = Field(pattern=r"^ORD-\d{3,10}$", description="Order ID formatted like ORD-1042")

@tool(args_schema=OrderLookupArgs)
def get_order_status(order_id: str) -> str:
    """Look up read-only shipping and invoice status for an order ID."""
    record = {"ORD-1042": {"status": "shipped", "refundable": True}}.get(order_id)
    if not record:
        return json.dumps({"found": False, "order_id": order_id})
    return json.dumps({"found": True, **record})

import logging

logger = logging.getLogger("triage.llm")

def classify_with_safe_fallback(structured_chain, messages: list) -> dict:
    try:
        out = structured_chain.invoke(messages)
        if out["parsing_error"] is None and out["parsed"] is not None:
            return {"status": "ok", "decision": out["parsed"].model_dump()}
        logger.warning("llm_parse_failed err=%s", out["parsing_error"])
    except TimeoutError:
        logger.warning("llm_timeout")
    return {"status": "fallback_manual_review", "needs_human_approval": True}

import logging
import time
from langchain_core.callbacks import BaseCallbackHandler

logger = logging.getLogger("triage.trace")

class MinimalTraceCallback(BaseCallbackHandler):
    def __init__(self, ticket_id: str):
        self.ticket_id = ticket_id
        self._t0 = 0.0

    def on_chat_model_start(self, serialized, messages, **kwargs):
        self._t0 = time.perf_counter()

    def on_llm_end(self, response, **kwargs):
        elapsed_ms = round((time.perf_counter() - self._t0) * 1000, 1)
        logger.info("llm_step ticket_id=%s latency_ms=%s", self.ticket_id, elapsed_ms)

    def on_tool_start(self, serialized, input_str, **kwargs):
        logger.info("tool_step ticket_id=%s tool=%s", self.ticket_id, serialized.get("name"))

