def build_retrieval_filter(verified_tenant_id: str, is_staff: bool, product: str | None = None) -> dict:
    allowed_audiences = ["customer_public", "internal_staff"] if is_staff else ["customer_public"]
    filt: dict = {
        "tenant_id": verified_tenant_id,  # Derived STRICTLY from verified auth context!
        "audience": {"$in": allowed_audiences},
        "is_active": True,
    }
    if product:
        filt["product"] = product
    return filt

def rrf_fuse(ranked_lists: list[list[str]], k: int = 60) -> list[tuple[str, float]]:
    scores: dict[str, float] = {}
    for ranking in ranked_lists:
        for rank_idx, doc_id in enumerate(ranking, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + (1.0 / (k + rank_idx))
    return sorted(scores.items(), key=lambda item: item[1], reverse=True)

def assemble_context(chunks: list[dict], max_chars: int = 8000) -> str:
    seen_ids: set[str] = set()
    parts: list[str] = []
    used = 0
    for c in chunks:
        cid = c["chunk_id"]
        if cid in seen_ids:
            continue
        block = f"[doc_id={c['doc_id']} | section={c['section']}]\n{c['text'].strip()}\n"
        if used + len(block) > max_chars:
            break
        seen_ids.add(cid)
        parts.append(block)
        used += len(block)
    return "\n---\n".join(parts)

def verify_citations(cited_doc_ids: list[str], retrieved_chunks: list[dict]) -> list[str]:
    valid_pool = {c["doc_id"] for c in retrieved_chunks}
    hallucinated = [doc_id for doc_id in cited_doc_ids if doc_id not in valid_pool]
    return hallucinated  # Non-empty -> flag hallucinated citation for manual review!

def evaluate_retrieval(eval_cases: list[dict], retrieve_ids_fn, k: int = 5) -> dict:
    hits = 0
    rr_sum = 0.0
    for case in eval_cases:
        expected = set(case["expected_doc_ids"])
        got = retrieve_ids_fn(case["query"], k=k)
        matched_ranks = [idx for idx, doc_id in enumerate(got, start=1) if doc_id in expected]
        if matched_ranks:
            hits += 1
            rr_sum += 1.0 / matched_ranks[0]
    n = len(eval_cases)
    return {"recall_at_k": round(hits / n, 3), "mrr": round(rr_sum / n, 3)}

from dataclasses import dataclass

@dataclass(frozen=True)
class VerifiedCallerScope:
    tenant_id: str
    can_view_internal: bool

def search_knowledge_base(query: str, scope: VerifiedCallerScope, vector_db) -> list[dict]:
    allowed_vis = ["public", "internal"] if scope.can_view_internal else ["public"]
    return vector_db.query(
        text=query,
        filter={
            "tenant_id": scope.tenant_id,
            "visibility": {"$in": allowed_vis},
        },
        top_k=5,
    )
